usage:
package main

import (
	"context"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	err := client.Realtime.Calls.Refer(
		context.TODO(),
		"call_id",
		openai.RealtimeCallReferParams{
			TargetURI: "string",
		},
	)
	if err != nil {
		panic(err.Error())
	}
}
